var t=`0237-gyros-pita`;var n=`world-0237`;var o=`GR`;var r=`southern-europe`;var a=4;var s=82;var g={en:`Gyros Pita`,ua:`Гірос у піті`};var l={en:`A traditional Greece dish made with chicken thigh, plain yogurt, lemon juice, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: куряче стегно, натуральний йогурт, лимонний сік, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 50 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 50 хвилин.`,t:[`marinating`],m:50,i:[[`chicken-thigh`,650,`g`],[`plain-yogurt`,140,`g`],[`lemon-juice`,40,`ml`],[`dried-oregano`,4,`g`],[`garlic`,4,`clove`]]},{en:`Roast in a preheated 190°C oven for about 27 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 27 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:27,i:[[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`pita-bread`,320,`g`],[`tomato`,230,`g`],[`red-onion`,90,`g`],[`tzatziki`,190,`g`]]}];var u={slug:t,id:n,country:`GR`,region:r,servings:4,minutes:82,title:g,text:l,steps:d};export{o as country,u as default,n as id,s as minutes,r as region,a as servings,t as slug,d as steps,l as text,g as title};